const DAY = 864e5;
// Срок прививки от даты рождения (у недоношенных тоже от даты рождения)
export function vaccineDate(item, dob) {
  if (item.ageDays) return dob + item.ageDays[0] * DAY;
  // «4,5 месяца» — четыре полных месяца и ещё половина месяца днями
  const whole = Math.floor(item.age), d = new Date(dob);
  d.setMonth(d.getMonth() + whole);
  return d.getTime() + Math.round((item.age - whole) * 30.44) * DAY;
}
export const vaccineTitle = (item) => {
  const dis = VACCINES.diseases[item.disease] || item.disease;
  return `${dis[0].toUpperCase()}${dis.slice(1)} — ${item.dose}`;
};
// Прививки по календарю, срок которых попадает в отрезок; marks — отметки родителя { id: {status, at} }
export function vaccinesBetween(dob, from, to, marks = {}) {
  return VACCINES.items
    .filter((it) => !it.riskGroup)
    .map((it) => ({ ...it, due: vaccineDate(it, dob), mark: marks[it.id] || null }))
    .filter((it) => it.due >= from && it.due < to && !(it.mark && it.mark.status === 'done'));
}
export function vaccineRows(dob, marks = {}) {
  return VACCINES.items.map((it) => ({ ...it, due: vaccineDate(it, dob), title: vaccineTitle(it), mark: marks[it.id] || null }));
}
